#!/usr/bin/env python3
"""Auréa — gestion locale multi-SCI. Python 3.10+. Interface et serveur autonomes.
Usage: python aurea.py [--desktop] [--demo] [--preview] [--port 8765] [--db data.db]
Seule dépendance facultative : pywebview (fenêtre native).
"""
import argparse, base64, csv, datetime as dt, hashlib, html, io, json, mimetypes
import os, secrets, sqlite3, sys, tempfile, threading, time, uuid, webbrowser
from pathlib import Path
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs

ROOT = Path(__file__).resolve().parent
DB = ROOT / 'data.db'
LOCK = threading.RLock()
TOKEN = secrets.token_urlsafe(32)
SERVER = None
WINDOW = None
PREVIEW = False
KINDS = ['properties','leases','partners','loans','calls','entries','tasks','documents']
DEFAULTS = {'theme':'dark','collapsed':False,'order':[], 'year':dt.date.today().year, 'last_page':'dashboard','last_tab':'overview','last_backup':'','owner':'Mon espace patrimonial','auto_backup':True}

def uid(): return uuid.uuid4().hex

def now(): return dt.datetime.now().isoformat(timespec='seconds')

class ClosingConnection(sqlite3.Connection):
    def __exit__(self, exc_type, exc_value, traceback):
        try: return super().__exit__(exc_type, exc_value, traceback)
        finally: self.close()

def connect(path=None):
    c = sqlite3.connect(str(path or DB), timeout=20, factory=ClosingConnection)
    c.row_factory = sqlite3.Row
    c.execute('PRAGMA foreign_keys=ON')
    c.execute('PRAGMA synchronous=FULL')
    return c

def init_db():
    DB.parent.mkdir(parents=True, exist_ok=True)
    with connect() as c:
        c.executescript('''CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS scis(id TEXT PRIMARY KEY,data TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS records(id TEXT PRIMARY KEY,sci TEXT NOT NULL REFERENCES scis(id) ON DELETE CASCADE,kind TEXT NOT NULL,data TEXT NOT NULL);
        CREATE INDEX IF NOT EXISTS records_scope ON records(sci,kind);
        CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,at TEXT NOT NULL,action TEXT NOT NULL,detail TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS imports(fingerprint TEXT PRIMARY KEY,at TEXT NOT NULL);
        ''')
        c.execute('INSERT OR IGNORE INTO meta VALUES(?,?)',('version','1'))
        c.execute('INSERT OR IGNORE INTO meta VALUES(?,?)',('settings',json.dumps(DEFAULTS)))

def settings(c):
    r=c.execute("SELECT value FROM meta WHERE key='settings'").fetchone()
    return {**DEFAULTS, **json.loads(r[0])}

def audit(c,action,detail): c.execute('INSERT INTO audit(at,action,detail) VALUES(?,?,?)',(now(),action,str(detail)[:500]))

def unpack(r): return {**json.loads(r['data']), 'id':r['id'], **({'sci':r['sci'],'kind':r['kind']} if 'sci' in r.keys() else {})}

def state(c):
    records=[]
    for r in c.execute('SELECT * FROM records ORDER BY rowid'):
        d=unpack(r); d.pop('blob',None); records.append(d)
    return {'scis':[unpack(r) for r in c.execute('SELECT * FROM scis ORDER BY rowid')], 'records':records, 'settings':settings(c),'audit':[dict(r) for r in c.execute('SELECT * FROM audit ORDER BY id DESC LIMIT 80')], 'preview':PREVIEW,'native':WINDOW is not None,'db_size':DB.stat().st_size,'saved_at':now()}

def clean(kind,data):
    if not isinstance(data,dict): raise ValueError('Données invalides.')
    d={k:v for k,v in data.items() if k not in ('id','sci','kind')}
    required={'sci':['name'],'properties':['name','address'],'leases':['tenant','property_id','start'],'partners':['name'],'loans':['name'],'calls':['lease_id','period','due'],'entries':['label','date','direction'],'tasks':['name','due'],'documents':['name']}
    for f in required.get(kind,[]):
        if not str(d.get(f,'')).strip(): raise ValueError('Champ obligatoire : '+f)
    for k,v in list(d.items()):
        if not isinstance(v,(str,int,float,bool,type(None))): raise ValueError('Valeur non prise en charge : '+k)
        if isinstance(v,str) and k!='blob' and len(v)>30000: raise ValueError('Texte trop long.')
    amounts=['capital','opening','value','purchase','surface','rent','charges','deposit','shares','cca','principal','balance','rate','monthly','amount','paid','interest','insurance']
    for f in amounts:
        if f in d:
            try:
                from decimal import Decimal, InvalidOperation
                v=Decimal(str(d[f] or 0))
                if not v.is_finite() or abs(v)>Decimal('1000000000000'): raise ValueError('Montant hors limites.')
                if f not in ('opening','cca') and v<0: raise ValueError('Le montant doit être positif : '+f)
                d[f]=float(v.quantize(Decimal('0.01')))
            except (InvalidOperation,TypeError): raise ValueError('Montant invalide : '+f)
    for f in ['date','due','start','end','acquired','dpe_date','balance_date','opening_date']:
        if d.get(f):
            try: dt.date.fromisoformat(d[f])
            except (ValueError,TypeError): raise ValueError('Date invalide : '+f)
    if d.get('end') and d.get('start') and d['end']<d['start']: raise ValueError('La fin précède le début du bail.')
    if kind=='sci':
        if d.get('regime','IR') not in ['IR','IS']: raise ValueError('Régime fiscal invalide.')
        if d.get('siren') and (not d['siren'].isdigit() or len(d['siren'])!=9): raise ValueError('Le SIREN doit comporter 9 chiffres.')
        if not d.get('opening_date'): d['opening_date']='2000-01-01'
    if kind=='entries' and d.get('direction') not in ['Recette','Dépense']: raise ValueError('Sens invalide.')
    if kind=='calls':
        try: dt.date.fromisoformat(d['period']+'-01')
        except (ValueError,TypeError): raise ValueError('Période invalide.')
    if kind=='documents' and d.get('blob'):
        try: raw=base64.b64decode(d['blob'],validate=True)
        except Exception: raise ValueError('Pièce jointe invalide.')
        if len(raw)>12*1024*1024: raise ValueError('Pièce jointe limitée à 12 Mo.')
        d['size']=len(raw)
    return d

REFS={'property_id':'properties','lease_id':'leases','call_id':'calls'}
def validate_refs(c,sci,d,ident=''):
    for f,k in REFS.items():
        if d.get(f):
            r=c.execute('SELECT * FROM records WHERE id=? AND sci=? AND kind=?',(d[f],sci,k)).fetchone()
            if not r: raise ValueError('Lien invalide ou appartenant à une autre SCI : '+f)
    if d.get('call_id'):
        call=unpack(c.execute('SELECT * FROM records WHERE id=?',(d['call_id'],)).fetchone())
        if d.get('direction')!='Recette': raise ValueError('Un encaissement de loyer doit être une recette.')
        paid=sum(json.loads(r[0]).get('amount',0) for r in c.execute("SELECT data FROM records WHERE kind='entries' AND sci=? AND id<>?",(sci,ident)) if json.loads(r[0]).get('call_id')==d['call_id'])
        if round(paid+d.get('amount',0),2)>round(call.get('rent',0)+call.get('charges',0),2): raise ValueError('Le paiement dépasse le solde de cet appel de loyer.')

def save_record(c,p):
    kind=p['kind']; sci=p.get('sci'); ident=p.get('id') or uid(); updating=bool(p.get('id'))
    if kind!='sci' and kind not in KINDS: raise ValueError('Type inconnu.')
    d=clean(kind,p['data'])
    table='scis' if kind=='sci' else 'records'
    previous=c.execute('SELECT * FROM '+table+' WHERE id=?',(ident,)).fetchone()
    if updating and not previous: raise ValueError('Cet élément a été supprimé. Actualisez la page.')
    if kind=='sci':
        c.execute('INSERT INTO scis(id,data) VALUES(?,?) ON CONFLICT(id) DO UPDATE SET data=excluded.data',(ident,json.dumps(d)))
    else:
        if not c.execute('SELECT id FROM scis WHERE id=?',(sci,)).fetchone(): raise ValueError('SCI introuvable.')
        if previous and previous['sci']!=sci: raise ValueError('Impossible de changer la SCI.')
        if kind=='documents' and previous and not d.get('blob'):
            old=json.loads(previous['data']); d.update({k:old[k] for k in ['blob','size','filename','mime'] if k in old})
        validate_refs(c,sci,d,ident)
        if kind=='calls':
            for r in c.execute("SELECT * FROM records WHERE sci=? AND kind='calls' AND id<>?",(sci,ident)):
                old=json.loads(r['data'])
                if old.get('lease_id')==d.get('lease_id') and old.get('period')==d.get('period'): raise ValueError('Un appel existe déjà pour ce bail et ce mois.')
            paid=sum(json.loads(r[0]).get('amount',0) for r in c.execute("SELECT data FROM records WHERE kind='entries' AND sci=?",(sci,)) if json.loads(r[0]).get('call_id')==ident)
            if previous and paid>0 and any(json.loads(previous['data']).get(f)!=d.get(f) for f in ['lease_id','period']): raise ValueError('Un appel déjà encaissé ne peut pas changer de bail ou de période.')
            if round(d.get('rent',0)+d.get('charges',0),2)<round(paid,2): raise ValueError('Le montant appelé est inférieur aux paiements déjà enregistrés.')
        c.execute('INSERT INTO records VALUES(?,?,?,?) ON CONFLICT(id) DO UPDATE SET data=excluded.data',(ident,sci,kind,json.dumps(d)))
    audit(c,'Modification' if previous else 'Création',d.get('name') or d.get('label') or d.get('tenant') or kind)
    return ident

def backup_bytes(c):
    fd,p=tempfile.mkstemp(suffix='.db'); os.close(fd)
    try:
        dst=sqlite3.connect(p); c.backup(dst); dst.close()
        return Path(p).read_bytes()
    finally: Path(p).unlink(missing_ok=True)

def make_safety_backup():
    folder=DB.parent/'sauvegardes'; folder.mkdir(exist_ok=True)
    with connect() as c: raw=backup_bytes(c)
    (folder/('aurea-'+dt.datetime.now().strftime('%Y%m%d-%H%M%S-%f')+'.db')).write_bytes(raw)

def export_bundle(c,p):
    ids=p.get('scis',[]); kinds=p.get('kinds',[])
    if not ids or not kinds: raise ValueError('Sélectionnez au moins une SCI et un type de données.')
    allrows=[unpack(r) for r in c.execute('SELECT * FROM records') if r['sci'] in ids]
    chosen={r['id']:r for r in allrows if r['kind'] in kinds}
    # Inclure les dépendances pour obtenir un export réimportable.
    lookup={r['id']:r for r in allrows}
    changed=True
    while changed:
        changed=False
        for r in list(chosen.values()):
            for f in REFS:
                if r.get(f) in lookup and r[f] not in chosen: chosen[r[f]]=lookup[r[f]]; changed=True
    return {'application':'Aurea','version':1,'exported_at':now(),'scis':[unpack(r) for r in c.execute('SELECT * FROM scis') if r['id'] in ids], 'records':list(chosen.values())}

def parse_import(p):
    fmt=p.get('format','json')
    if fmt=='json':
        try: b=json.loads(p['text'])
        except Exception: raise ValueError('Fichier JSON illisible.')
        if not isinstance(b,dict) or b.get('application')!='Aurea' or b.get('version')!=1: raise ValueError('Choisissez un export JSON Auréa version 1.')
        if not isinstance(b.get('scis'),list) or not isinstance(b.get('records'),list): raise ValueError('Export incomplet.')
        if len(b['records'])>40000: raise ValueError('Import limité à 40 000 lignes.')
        ids=set()
        for s in b['scis']:
            if not s.get('id') or s['id'] in ids: raise ValueError('Identifiants SCI invalides.')
            ids.add(s['id']); clean('sci',s)
        seen=set()
        for r in b['records']:
            if r.get('kind') not in KINDS or r.get('sci') not in ids or not r.get('id') or r['id'] in seen: raise ValueError('Références invalides dans cet export.')
            seen.add(r['id']); clean(r['kind'],r)
        return b
    if fmt!='csv': raise ValueError('Format non pris en charge.')
    text=p.get('text','').lstrip('\ufeff')
    try: dialect=csv.Sniffer().sniff(text[:4000],delimiters=';,\t')
    except csv.Error: dialect=csv.excel; dialect.delimiter=';'
    reader=csv.DictReader(io.StringIO(text),dialect=dialect)
    if not set(['date','label','direction','category','amount']).issubset(reader.fieldnames or []): raise ValueError('En-têtes requis : date;label;direction;category;amount')
    rows=[]; sources={}
    for i,r in enumerate(reader,2):
        try:
            d={k:r.get(k,'') for k in ['date','label','direction','category','amount']}
            d['amount']=float(d['amount'].replace(' ','').replace(',','.'))
            name=(r.get('sci') or '').strip()
            source='csv_'+hashlib.sha256(name.encode()).hexdigest()[:16] if name else 'csv'
            sources[source]={'id':source,'name':name or 'Mouvements CSV sans société renseignée'}
            rows.append({**clean('entries',d),'id':uid(),'sci':source,'kind':'entries'})
        except Exception as e: raise ValueError('Ligne '+str(i)+' : '+str(e))
    if not rows or len(rows)>40000: raise ValueError('Le CSV doit contenir entre 1 et 40 000 lignes.')
    return {'application':'Aurea','version':1,'scis':list(sources.values()),'records':rows}

def import_bundle(c,p):
    b=parse_import(p); mapping=p.get('mapping',{})
    selected=[s for s in b['scis'] if s['id'] in mapping]
    if not selected: raise ValueError('Sélectionnez les SCI à importer et leur destination.')
    if p.get('format')=='csv' and any(dest=='new' for dest in mapping.values()): raise ValueError('Sélectionnez une SCI existante pour le CSV.')
    fp=hashlib.sha256((p['text']+json.dumps(mapping,sort_keys=True)).encode()).hexdigest()
    if c.execute('SELECT 1 FROM imports WHERE fingerprint=?',(fp,)).fetchone(): raise ValueError('Ce fichier a déjà été importé vers ces destinations.')
    sci_map={}
    for s in selected:
        dest=mapping[s['id']]
        if dest=='new':
            d=clean('sci',s); d['name']=d['name']+' (import)'; new=uid()
            c.execute('INSERT INTO scis VALUES(?,?)',(new,json.dumps(d))); sci_map[s['id']]=new
        else:
            if not c.execute('SELECT 1 FROM scis WHERE id=?',(dest,)).fetchone(): raise ValueError('SCI de destination introuvable.')
            sci_map[s['id']]=dest
    rows=[r for r in b['records'] if r['sci'] in sci_map]
    idmap={r['id']:uid() for r in rows}
    for r in rows:
        d=clean(r['kind'],r)
        for f in REFS:
            if d.get(f):
                if d[f] not in idmap: raise ValueError('Dépendance absente : '+f+'. Exportez aussi les données liées.')
                d[f]=idmap[d[f]]
        c.execute('INSERT INTO records VALUES(?,?,?,?)',(idmap[r['id']],sci_map[r['sci']],r['kind'],json.dumps(d)))
    for r in rows:
        v=c.execute('SELECT * FROM records WHERE id=?',(idmap[r['id']],)).fetchone()
        validate_refs(c,v['sci'],json.loads(v['data']),v['id'])
    c.execute('INSERT INTO imports VALUES(?,?)',(fp,now())); audit(c,'Import',str(len(rows))+' éléments / '+str(len(selected))+' SCI')
    return len(rows)

def restore(raw):
    if len(raw)>100*1024*1024 or not raw.startswith(b'SQLite format 3\x00'): raise ValueError('Sauvegarde SQLite non valide (100 Mo maximum).')
    fd,p=tempfile.mkstemp(suffix='.db'); os.close(fd)
    try:
        Path(p).write_bytes(raw)
        src=connect(p)
        try:
            if src.execute('PRAGMA integrity_check').fetchone()[0]!='ok': raise ValueError('Base endommagée.')
            if src.execute("SELECT value FROM meta WHERE key='version'").fetchone()[0]!='1': raise ValueError('Version non prise en charge.')
            if src.execute('PRAGMA foreign_key_check').fetchone(): raise ValueError('Relations incohérentes.')
            json.loads(src.execute("SELECT value FROM meta WHERE key='settings'").fetchone()[0])
            for r in src.execute('SELECT * FROM scis'): clean('sci',json.loads(r['data']))
            for r in src.execute('SELECT * FROM records'):
                if r['kind'] not in KINDS: raise ValueError('Type de données inconnu.')
                d=clean(r['kind'],json.loads(r['data'])); validate_refs(src,r['sci'],d,r['id'])
            tables={t:[tuple(r) for r in src.execute('SELECT * FROM '+t)] for t in ['meta','scis','records','audit','imports']}
        finally: src.close()
        make_safety_backup()
        with connect() as c:
            for t in ['records','scis','meta','audit','imports']: c.execute('DELETE FROM '+t)
            for t,rows in tables.items():
                if rows: c.executemany('INSERT INTO '+t+' VALUES('+','.join('?' for _ in rows[0])+')',rows)
            audit(c,'Restauration','Sauvegarde complète restaurée ; copie préalable dans sauvegardes/.')
    except sqlite3.Error: raise ValueError('Ce fichier n’est pas une sauvegarde Auréa valide.')
    finally: Path(p).unlink(missing_ok=True)

def sync_exit():
    with LOCK:
        with connect() as c:
            if c.execute('PRAGMA integrity_check').fetchone()[0]!='ok': raise ValueError('Erreur d’intégrité. Fermeture annulée.')
            auto=settings(c).get('auto_backup',True)
            audit(c,'Fermeture','Écritures validées et intégrité SQLite vérifiée.')
        if auto: make_safety_backup()

def demo():
    with connect() as c:
        if c.execute('SELECT count(*) FROM scis').fetchone()[0]: return
        demos=[('SCI Les Oliviers','IR','#c8ae75','Aix-en-Provence',12500),('SCI Horizon','IS','#879ad8','Lyon',18350),('SCI Bellevue','IR','#70b7a6','Bordeaux',9700)]
        for ix,(name,regime,color,city,opening) in enumerate(demos):
            s=save_record(c,{'kind':'sci','data':{'name':name,'regime':regime,'color':color,'city':city,'address':city,'manager':'Camille Laurent','capital':10000,'opening':opening,'opening_date':'2026-01-01','closing':'31/12','notes':'Données fictives de démonstration.'}})
            props=[]; leases=[]
            names=[['Résidence des Oliviers','Appartement Mazarin'],['Les Terrasses du Rhône','Atelier des Brotteaux'],['Maison des Chartrons','Appartement Saint-Pierre']][ix]
            for j,n in enumerate(names):
                prop=save_record(c,{'kind':'properties','sci':s,'data':{'name':n,'address':str(12+j*8)+' rue des Jardins, '+city,'type':'Appartement' if j else 'Immeuble','value':[420000,260000,510000,185000,360000,245000][ix*2+j],'purchase':200000,'surface':65+j*20,'status':'Loué' if not(ix==2 and j==1) else 'Vacant','dpe':['C','D','B'][ix],'dpe_date':'2030-04-15','acquired':'2020-06-15'}}); props.append(prop)
                if ix==2 and j==1: continue
                rent=[1450,980,1820,850,1250][len(leases)+ix*2] if ix<2 else 1250
                lease=save_record(c,{'kind':'leases','sci':s,'data':{'tenant':[['Thomas & Léa Martin','Sophie Bernard'],['Studio Aster','Julien Moreau'],['Alice Petit']][ix][j],'email':'locataire@example.com','property_id':prop,'start':'2025-01-01','end':'2028-01-01','rent':rent,'charges':90,'deposit':rent,'type':'Habitation nue','status':'Actif','notes':''}}); leases.append(lease)
                for m in range(1,11):
                    call=save_record(c,{'kind':'calls','sci':s,'data':{'lease_id':lease,'period':f'2026-{m:02d}','due':f'2026-{m:02d}-05','rent':rent,'charges':90}})
                    if not(ix==0 and j==1 and m==10): save_record(c,{'kind':'entries','sci':s,'data':{'label':'Loyer '+n,'date':f'2026-{m:02d}-05','direction':'Recette','category':'Loyers','amount':rent+90,'call_id':call}})
            for m in range(1,11):
                save_record(c,{'kind':'entries','sci':s,'data':{'label':'Entretien & gestion','date':f'2026-{m:02d}-12','direction':'Dépense','category':'Entretien','amount':350+ix*120+(m%3)*90}})
                save_record(c,{'kind':'entries','sci':s,'data':{'label':'Échéance emprunt','date':f'2026-{m:02d}-10','direction':'Dépense','category':'Emprunt (capital + intérêts)','amount':820+ix*170}})
            for n,shares in [('Camille Laurent',60),('Alexandre Laurent',40)]: save_record(c,{'kind':'partners','sci':s,'data':{'name':n,'shares':shares,'cca':5000,'role':'Gérant associé' if shares==60 else 'Associé','email':'associe@example.com'}})
            save_record(c,{'kind':'loans','sci':s,'data':{'name':'Financement immobilier','bank':'Banque patrimoniale','principal':280000,'balance':215000+ix*15000,'balance_date':'2026-10-01','rate':2.4,'monthly':820+ix*170,'start':'2020-06-01','end':'2040-06-01'}})
            save_record(c,{'kind':'tasks','sci':s,'data':{'name':['Taxe foncière','Renouveler l’assurance PNO','Préparer le rapport de gestion'][ix],'due':['2026-10-20','2026-10-28','2026-11-12'][ix],'category':['Fiscalité','Assurance','Juridique'][ix],'status':'À faire','notes':'Échéance fictive à adapter à votre situation.'}})
        st=settings(c); st['demo']=True; c.execute("UPDATE meta SET value=? WHERE key='settings'",(json.dumps(st),)); c.execute('DELETE FROM audit'); audit(c,'Démonstration','Jeu fictif — 3 SCI, 6 biens, 5 baux.')

class Handler(BaseHTTPRequestHandler):
    def log_message(self,format,*args): pass
    def reply(self,data,status=200,mime='application/json; charset=utf-8',filename=None):
        raw=json.dumps(data,ensure_ascii=False).encode() if mime.startswith('application/json') and not isinstance(data,bytes) else data.encode() if isinstance(data,str) else data
        self.send_response(status); self.send_header('Content-Type',mime); self.send_header('Content-Length',str(len(raw)))
        self.send_header('Cache-Control','no-store'); self.send_header('X-Content-Type-Options','nosniff'); self.send_header('Referrer-Policy','no-referrer')
        if filename: self.send_header('Content-Disposition','attachment; filename="'+filename+'"')
        self.end_headers(); self.wfile.write(raw)
    def allowed_host(self):
        host=self.headers.get('Host','').split(':')[0].lower()
        return PREVIEW or host in ('127.0.0.1','localhost')
    def do_GET(self):
        if not self.allowed_host(): return self.reply({'error':'Accès local uniquement.'},403)
        path=urlparse(self.path).path
        if path in ['/','/index.html']:
            return self.reply(HTML.replace('__TOKEN__',TOKEN),mime='text/html; charset=utf-8')
        if path=='/favicon.ico': return self.reply(b'',mime='image/x-icon')
        if self.headers.get('X-Aurea-Token')!=TOKEN: return self.reply({'error':'Session invalide. Rechargez la page.'},403)
        try:
            with LOCK,connect() as c:
                if path=='/api/state': return self.reply(state(c))
                if path=='/api/document':
                    ident=parse_qs(urlparse(self.path).query).get('id',[''])[0]
                    r=c.execute("SELECT * FROM records WHERE id=? AND kind='documents'",(ident,)).fetchone()
                    if not r: raise ValueError('Document introuvable.')
                    d=json.loads(r['data'])
                    if not d.get('blob'): raise ValueError('Aucun fichier joint à ce document.')
                    return self.reply(base64.b64decode(d['blob']),mime='application/octet-stream',filename='document'+Path(d.get('filename','document')).suffix)
                self.reply({'error':'Page introuvable.'},404)
        except Exception as e: self.reply({'error':str(e)},400)
    def do_POST(self):
        if not self.allowed_host(): return self.reply({'error':'Accès local uniquement.'},403)
        if self.headers.get('X-Aurea-Token')!=TOKEN: return self.reply({'error':'Session invalide. Rechargez la page.'},403)
        try:
            n=int(self.headers.get('Content-Length',0))
            if n>145*1024*1024: raise ValueError('Fichier trop volumineux.')
            p=json.loads(self.rfile.read(n)); path=urlparse(self.path).path
            with LOCK:
                if path=='/api/native-save':
                    if not WINDOW: raise ValueError('Disponible uniquement dans la fenêtre native.')
                    import webview
                    name=Path(str(p.get('filename','aurea-export')).replace('\\','/')).name
                    chosen=WINDOW.create_file_dialog(webview.SAVE_DIALOG,save_filename=name)
                    if not chosen: raise ValueError('Enregistrement annulé.')
                    destination=chosen if isinstance(chosen,str) else chosen[0]
                    raw=base64.b64decode(p['blob'],validate=True)
                    dest=Path(destination)
                    if dest.resolve()==DB.resolve(): raise ValueError('Choisissez un autre fichier que la base data.db actuellement ouverte.')
                    fd,temp=tempfile.mkstemp(prefix='.aurea-',dir=str(dest.parent)); os.close(fd)
                    try:
                        with open(temp,'wb') as f: f.write(raw); f.flush(); os.fsync(f.fileno())
                        os.replace(temp,dest)
                    finally: Path(temp).unlink(missing_ok=True)
                    return self.reply({'ok':True})
                if path=='/api/restore':
                    restore(base64.b64decode(p['blob'],validate=True))
                    return self.reply({'ok':True})
                if path=='/api/quit':
                    sync_exit(); self.reply({'ok':True,'preview':PREVIEW,'native':WINDOW is not None})
                    if not PREVIEW:
                        def close():
                            if WINDOW: WINDOW.destroy()
                            SERVER.shutdown()
                        threading.Timer(.5,close).start()
                    return
                if path=='/api/backup':
                    with connect() as c:
                        st=settings(c); st['last_backup']=now(); c.execute("UPDATE meta SET value=? WHERE key='settings'",(json.dumps(st),)); audit(c,'Sauvegarde','Export complet SQLite, documents et réglages inclus.')
                    with connect() as c: raw=backup_bytes(c)
                    return self.reply(raw,mime='application/octet-stream',filename='aurea-sauvegarde-'+dt.date.today().isoformat()+'.db')
                with connect() as c:
                    if path=='/api/save':
                        ident=save_record(c,p); c.commit(); return self.reply({'ok':True,'id':ident})
                    if path=='/api/settings':
                        st=settings(c)
                        for k,v in p.items():
                            if k in DEFAULTS or k=='demo': st[k]=v
                        if st['theme'] not in ['dark','light']: raise ValueError('Thème invalide.')
                        c.execute("UPDATE meta SET value=? WHERE key='settings'",(json.dumps(st),)); c.commit(); return self.reply({'ok':True})
                    if path=='/api/delete':
                        kind=p['kind']; ident=p['id']
                        if kind=='sci':
                            r=c.execute('SELECT * FROM scis WHERE id=?',(ident,)).fetchone()
                            if not r: raise ValueError('SCI introuvable.')
                            if p.get('confirmation')!=json.loads(r['data'])['name']: raise ValueError('Saisissez le nom exact de la SCI.')
                            c.execute('DELETE FROM scis WHERE id=?',(ident,))
                        else:
                            if kind not in KINDS: raise ValueError('Type invalide.')
                            for r in c.execute('SELECT * FROM records'):
                                if any(json.loads(r['data']).get(f)==ident for f in REFS): raise ValueError('Cet élément est utilisé. Supprimez d’abord les éléments liés (baux, appels ou paiements).')
                            c.execute('DELETE FROM records WHERE id=? AND kind=?',(ident,kind))
                        audit(c,'Suppression',kind+' / '+ident); c.commit(); return self.reply({'ok':True})
                    if path=='/api/export':
                        b=export_bundle(c,p); fmt=p.get('format','json')
                        if fmt=='json': return self.reply(json.dumps(b,ensure_ascii=False,indent=2).encode(),mime='application/json',filename='aurea-export.json')
                        if fmt!='csv': raise ValueError('Format inconnu.')
                        # CSV plat de mouvements uniquement, valeurs sûres pour tableur.
                        if p.get('kinds')!=['entries']: raise ValueError('Le CSV est réservé aux mouvements de trésorerie.')
                        stream=io.StringIO(); w=csv.writer(stream,delimiter=';'); w.writerow(['sci','date','label','direction','category','amount'])
                        names={s['id']:s['name'] for s in b['scis']}
                        def safe(v):
                            v=str(v)
                            return "'"+v if v.startswith(('=','+','-','@','\t','\r')) else v
                        for r in b['records']:
                            if r['kind']=='entries': w.writerow([safe(names[r['sci']]),r.get('date',''),safe(r.get('label','')),r.get('direction',''),safe(r.get('category','')),str(r.get('amount',0)).replace('.',',')])
                        return self.reply(('\ufeff'+stream.getvalue()).encode(),mime='text/csv; charset=utf-8',filename='aurea-mouvements.csv')
                    if path=='/api/import-preview':
                        b=parse_import(p); return self.reply({'scis':b['scis'],'counts':{s['id']:{k:sum(r['sci']==s['id'] and r['kind']==k for r in b['records']) for k in KINDS} for s in b['scis']},'rows':b['records'][:5] if p.get('format')=='csv' else []})
                    if path=='/api/import':
                        count=import_bundle(c,p); c.commit(); return self.reply({'ok':True,'count':count})
                    if path=='/api/generate-calls':
                        period=p['period']; first=dt.date.fromisoformat(period+'-01'); count=0
                        for r in c.execute("SELECT * FROM records WHERE kind='leases' AND sci=?",(p['sci'],)).fetchall():
                            d=json.loads(r['data'])
                            if d.get('status')!='Actif' or d.get('start','')[:7]>period or (d.get('end') and d['end'][:7]<period): continue
                            if any(json.loads(x[0]).get('lease_id')==r['id'] and json.loads(x[0]).get('period')==period for x in c.execute("SELECT data FROM records WHERE kind='calls' AND sci=?",(p['sci'],))): continue
                            save_record(c,{'kind':'calls','sci':p['sci'],'data':{'lease_id':r['id'],'period':period,'due':period+'-05','rent':d.get('rent',0),'charges':d.get('charges',0),'notes':'Montant mensuel. Vérifier les éventuels proratas.'}}); count+=1
                        c.commit(); return self.reply({'ok':True,'count':count})
                    if path=='/api/reset-demo':
                        if p.get('confirmation')!='EFFACER': raise ValueError('Confirmation manquante.')
                        if not settings(c).get('demo'): raise ValueError('Cette base n’est pas une démonstration.')
                        c.execute('DELETE FROM records'); c.execute('DELETE FROM scis'); c.execute('DELETE FROM imports'); st=settings(c); st['demo']=False; st['order']=[]; st['last_page']='dashboard'; c.execute("UPDATE meta SET value=? WHERE key='settings'",(json.dumps(st),)); audit(c,'Réinitialisation','Données de démonstration effacées.'); c.commit(); return self.reply({'ok':True})
                    self.reply({'error':'Action inconnue.'},404)
        except (ValueError,KeyError,TypeError,sqlite3.Error) as e: self.reply({'error':str(e)},400)
        except Exception as e: self.reply({'error':'Opération impossible : '+str(e)},500)

